class Model {
    private int count;
    void increment() { count++; }
    int get() { return count; }
}
class View { void show(int n) { System.out.println("Итого: " + n); } }
class Controller {
    private final Model model; private final View view;
    Controller(Model m, View v) { model = m; view = v; }
    void click() { model.increment(); view.show(model.get()); }
}
public class Main {
    public static void main(String[] args) {
        new Controller(new Model(), new View()).click();
    }
}

